```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        // The subscriptions store holds one newline-separated list of feed URLs
        // under the key "urls". A missing key yields an empty, present list.
        let urls = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
